import{initFieldGuide}from'./field-guide.js';
import { initJourney } from './journey.js';
import { initCatalog } from './catalog.js';
const catalog=await initCatalog();
const journey=initJourney({showMission:catalog.showRoute,hideMission:catalog.hideDetail});
catalog.connect(journey);
initFieldGuide();
function clock(){document.querySelector('#clock').textContent='MARS / '+new Date().toISOString().slice(11,19)+' UTC'}clock();setInterval(clock,1000);
// The user explicitly requested slow automatic Mars rotation.
const MARS_ROTATION_SECONDS=180;
let paused=false,sunlightOn=true,resetView=()=>{};const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;function syncRotation(){document.body.classList.toggle('is-paused',paused);const rot=document.querySelector('#rotate');if(rot){rot.textContent=paused?'▶ Resume rotation':'II Pause rotation';rot.setAttribute('aria-pressed',String(paused));}const b=document.querySelector('#hero-rotate');if(b){b.innerHTML=paused?'▶ <span>RESUME MARS</span>':'II <span>MARS IN MOTION</span>';b.setAttribute('aria-pressed',String(paused));b.setAttribute('aria-label',paused?'Resume Mars rotation':'Pause Mars rotation');}}
syncRotation();function toggleRotation(){paused=!paused;syncRotation();document.querySelector('#viewer-status').textContent=paused?'Rotation paused':'Rotation resumed'}const rotBtn=document.querySelector('#rotate');if(rotBtn)rotBtn.onclick=toggleRotation;const heroRot=document.querySelector('#hero-rotate');if(heroRot)heroRot.onclick=toggleRotation;
document.querySelector('#lighting').onclick=e=>{sunlightOn=!sunlightOn;e.currentTarget.textContent=sunlightOn?'◐ Sunlight on':'○ Neutral light';e.currentTarget.setAttribute('aria-pressed',String(sunlightOn));document.body.classList.toggle('neutral-light',!sunlightOn)};document.querySelector('#reset').onclick=()=>resetView();
async function start3D(){const THREE=await import('./assets/three.js');const loader=new THREE.TextureLoader();const texture=loader.load('./assets/mars.jpg');texture.colorSpace=THREE.SRGBColorSpace;function create(container,hero){const scene=new THREE.Scene();const camera=new THREE.PerspectiveCamera(35,1,.1,100);camera.position.z=hero?5.2:4.6;const renderer=new THREE.WebGLRenderer({alpha:true,antialias:true,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.6));renderer.setClearColor(0,0);container.append(renderer.domElement);renderer.domElement.tabIndex=0;renderer.domElement.setAttribute('role','img');renderer.domElement.setAttribute('aria-label','Mars globe. Drag or use arrow keys to rotate.');const ambient=new THREE.AmbientLight(0xffd9bd,.23);scene.add(ambient);const sun=new THREE.DirectionalLight(0xfff5e8,3.4);sun.position.set(-3,2.5,4);scene.add(sun);const group=new THREE.Group();scene.add(group);const mars=new THREE.Mesh(new THREE.SphereGeometry(1,80,60),new THREE.MeshPhongMaterial({map:texture,specular:0x1c0e09,shininess:2}));group.add(mars);const atmosphere=new THREE.Mesh(new THREE.SphereGeometry(1.025,64,48),new THREE.ShaderMaterial({vertexShader:'varying vec3 vNormal; varying vec3 vPosition; void main(){vNormal=normalize(normalMatrix*normal);vec4 p=modelViewMatrix*vec4(position,1.);vPosition=p.xyz;gl_Position=projectionMatrix*p;}',fragmentShader:'varying vec3 vNormal; varying vec3 vPosition; void main(){float edge=1.-max(dot(normalize(vNormal),normalize(-vPosition)),0.);float a=pow(edge,4.)*.6;gl_FragColor=vec4(.85,.35,.16,a*.35);}',transparent:true,depthWrite:false}));group.add(atmosphere);group.rotation.set(.12,2.4,-.16);renderer.domElement.onkeydown=e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();group.rotation.y+=e.key==='ArrowLeft'?-.15:.15}};function resize(){const w=container.clientWidth,h=container.clientHeight;renderer.setSize(w,h,false);camera.aspect=w/h;camera.updateProjectionMatrix()}resize();new ResizeObserver(resize).observe(container);if(hero){document.querySelector('.fallback-globe').style.display='none'}{let down=false,px=0,py=0;renderer.domElement.onpointerdown=e=>{down=true;px=e.clientX;py=e.clientY;renderer.domElement.setPointerCapture(e.pointerId)};renderer.domElement.onpointermove=e=>{if(!down)return;group.rotation.y+=(e.clientX-px)*.008;group.rotation.x=Math.max(-1,Math.min(1,group.rotation.x+(e.clientY-py)*.005));px=e.clientX;py=e.clientY};renderer.domElement.onpointerup=renderer.domElement.onpointercancel=()=>down=false;if(!hero)resetView=()=>{group.rotation.set(.12,2.4,-.16);document.querySelector('#viewer-status').textContent='View reset'}}return{renderer,scene,camera,group,sun,ambient,hero,container}}const hero=create(document.querySelector('#space'),true),viewer=create(document.querySelector('#viewer'),false);let last=0;function frame(t){requestAnimationFrame(frame);if(document.hidden)return;const dt=Math.min((t-last)/1000,.05);last=t;[hero,viewer].forEach(v=>{if(!paused)v.group.rotation.y+=dt*(Math.PI*2/MARS_ROTATION_SECONDS);v.sun.intensity=sunlightOn?3.4:1.0;v.ambient.intensity=sunlightOn?.23:1.4;if(v.hero){const mobile=innerWidth<760;const p=0;v.camera.position.z=(mobile?5.2:4.1)+p*1.5;v.group.position.set(mobile?.28:1.05, mobile?.32:.12,0);v.group.scale.setScalar(mobile?1:1.1)}const r=v.container.getBoundingClientRect();if(r.bottom>0&&r.top<innerHeight&&r.right>0&&r.left<innerWidth)v.renderer.render(v.scene,v.camera)})}requestAnimationFrame(frame)}start3D().catch(()=>{const hero=document.querySelector('.fallback-globe');hero.style.display='';hero.classList.add('textured');document.querySelectorAll('#space canvas,#viewer canvas').forEach(c=>c.remove());const globe=document.createElement('div');globe.className='css-mars textured';document.querySelector('#viewer').append(globe);let angle=0;[hero,globe].forEach(g=>{let down=false,px=0;g.tabIndex=0;g.setAttribute('role','img');g.setAttribute('aria-label','Mars globe. Drag or use arrow keys to rotate.');g.onkeydown=e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();angle+=e.key==='ArrowLeft'?-8:8}};g.onpointerdown=e=>{down=true;px=e.clientX;g.setPointerCapture(e.pointerId)};g.onpointermove=e=>{if(down){angle+=(e.clientX-px)*.4;px=e.clientX}};g.onpointerup=g.onpointercancel=()=>down=false});resetView=()=>{angle=0;document.querySelector('#viewer-status').textContent='View reset'};let last=0;function animate(t){requestAnimationFrame(animate);if(document.hidden)return;const dt=Math.min((t-last)/1000,.05);last=t;if(!paused)angle+=dt*(200/MARS_ROTATION_SECONDS);[hero,globe].forEach(g=>{g.style.backgroundPosition=`${angle}% center`;g.classList.toggle('neutral-light',!sunlightOn)})}requestAnimationFrame(animate)});


const arrowMarkup='<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.2" aria-hidden="true"><path d="M5 19 19 5M5 5h14v14"/></svg>';document.querySelectorAll('.circle-link b,.nav-cta>span,.light-button>span,.wordmark>span').forEach(el=>el.innerHTML=arrowMarkup);
